// Ambient declarations for `with { type: "file" }` imports of prebuilt assets; each resolves to a path string.
declare module "*/generated/page.js" {
  const file: string;
  export default file;
}
declare module "*/generated/player.js" {
  const file: string;
  export default file;
}
declare module "*/generated/terminal.css" {
  const file: string;
  export default file;
}
declare module "*/generated/ghostty-vt.wasm" {
  const file: string;
  export default file;
}
